package com.example.data.sync.backup

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.long
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.util.Calendar
import java.util.TimeZone

/**
 * G8 (PARITY_FIX_PLAN §9): Opti's backup-tier path / stamp / boundary helpers, generated by
 * tools/gen_opti_fixtures.mjs in UTC with `syncDeviceId() = "fx-device-0001"` and
 * `FIXED_NOW = 2026-09-24T12:00:00Z` as the tiers' `lastTs`.
 */
class BackupTierG8Test {
    private val utc = TimeZone.getTimeZone("UTC")
    private val fixedNow = 1790251200000L

    private fun fixture(name: String): String {
        var dir: File? = File("").absoluteFile
        while (dir != null) {
            val f = File(dir, "fixtures/opti/G8/$name")
            if (f.exists()) return f.readText()
            dir = dir.parentFile
        }
        error("fixtures/opti/G8/$name not found")
    }

    @Test fun g8_stamps() {
        val rows = Json.parseToJsonElement(fixture("stamps.json")) as JsonArray
        assertEquals(3, rows.size)
        for (r in rows) {
            val o = r.jsonObject
            assertEquals(o["label"]!!.jsonPrimitive.content, o["stamp"]!!.jsonPrimitive.content,
                BackupTierEngine.stamp(o["ts"]!!.jsonPrimitive.long, utc))
        }
    }

    @Test fun g8_paths() {
        val paths = Json.parseToJsonElement(fixture("paths.json")) as JsonObject
        assertEquals(8, paths.size)
        val dev6 = BackupTierEngine.deviceShort("fx-device-0001")
        val stamp = BackupTierEngine.stamp(fixedNow, utc)
        for (t in BkTier.ORDER) for (slot in 0..1) {
            assertEquals(paths["${t.key}_$slot"]!!.jsonPrimitive.content, BackupTierEngine.path(t, dev6, slot, stamp))
        }
    }

    @Test fun g8_nextBoundaries() {
        val b = Json.parseToJsonElement(fixture("next_boundaries.json")) as JsonObject
        assertEquals(4, b.size)
        for (t in BkTier.ORDER) {
            assertEquals(t.key, b[t.key]!!.jsonPrimitive.long, BackupTierEngine.nextBoundary(t, fixedNow, utc))
        }
    }
}

/** auto-backup-boundary.test.js B1-B8 (local time; here Europe/Bratislava). */
class BackupBoundaryTest {
    private val tz = TimeZone.getTimeZone("Europe/Bratislava")
    private fun local(y: Int, m: Int, d: Int, h: Int = 0, min: Int = 0): Long =
        Calendar.getInstance(tz).apply { clear(); set(y, m - 1, d, h, min, 0) }.timeInMillis

    @Test fun b1_neverFired_isDueAtOnce() {
        for (t in BkTier.ORDER) assertEquals(0L, BackupTierEngine.nextBoundary(t, 0L, tz))
    }

    @Test fun b2_fourHour_isLastPlusFourHours() {
        val last = local(2026, 7, 1, 12)
        assertEquals(last + 4 * 3_600_000L, BackupTierEngine.nextBoundary(BkTier.FOUR_HOUR, last, tz))
    }

    @Test fun b3_b4_daily_isTheNextLocalMidnight() {
        assertEquals(local(2026, 7, 2), BackupTierEngine.nextBoundary(BkTier.DAILY, local(2026, 7, 1, 9), tz))
        assertEquals(local(2026, 7, 2), BackupTierEngine.nextBoundary(BkTier.DAILY, local(2026, 7, 1, 0, 30), tz))
    }

    @Test fun b5_weekly_isAMondayMidnight_strictlyAfter_withinAWeek() {
        for (i in 0 until 7) {
            val last = local(2026, 7, 1 + i, 13)
            val b = BackupTierEngine.nextBoundary(BkTier.WEEKLY, last, tz)
            val c = Calendar.getInstance(tz).apply { timeInMillis = b }
            assertEquals(Calendar.MONDAY, c.get(Calendar.DAY_OF_WEEK))
            assertEquals(0, c.get(Calendar.HOUR_OF_DAY)); assertEquals(0, c.get(Calendar.MINUTE))
            assertTrue(b > last)
            assertTrue(b - last <= 7 * 86_400_000L + 3_600_000L)
        }
    }

    @Test fun b6_monthly_isTheFirstOfNextMonth_rollingTheYear() {
        assertEquals(local(2026, 8, 1), BackupTierEngine.nextBoundary(BkTier.MONTHLY, local(2026, 7, 15), tz))
        assertEquals(local(2027, 1, 1), BackupTierEngine.nextBoundary(BkTier.MONTHLY, local(2026, 12, 20), tz))
    }

    @Test fun b8_fromNow_isStrictlyLater() {
        val now = local(2026, 3, 29, 1, 30) // the Europe DST edge day
        for (t in BkTier.ORDER) assertTrue(t.key, BackupTierEngine.nextBoundary(t, now, tz) > now)
    }
}
